#!/usr/bin/env bash
# Read-only: quote lines created in QA since the date flows were deployed (26 Nov 11:24 UTC) - prices, dates, term fields
sf data query --query "SELECT Quote.QuoteNumber, Quote.RLM_TermMonths__c, Quote.StartDate, Product2.ProductCode, PricebookEntry.ProductSellingModel.SellingModelType, Quantity, BillingFrequency, StartDate, EndDate, SubscriptionTerm, SubscriptionTermUnit, PricingTermCount, ListPrice, UnitPrice, NetUnitPrice, TotalPrice, CreatedDate, LastModifiedDate FROM QuoteLineItem WHERE CreatedDate >= 2026-11-26T11:20:00Z ORDER BY CreatedDate DESC LIMIT 15" --target-org target --json 2>&1 | jq -r '.result.records[]? | [.Quote.QuoteNumber, "qTerm", .Quote.RLM_TermMonths__c, .Quote.StartDate, .Product2.ProductCode, .PricebookEntry.ProductSellingModel.SellingModelType, "qty", .Quantity, .BillingFrequency, .StartDate, .EndDate, "subTerm", .SubscriptionTerm, .SubscriptionTermUnit, "ptc", .PricingTermCount, "list", .ListPrice, "unit", .UnitPrice, "net", .NetUnitPrice, "total", .TotalPrice, .CreatedDate[11:19], .LastModifiedDate[11:19]] | map(tostring) | join(" ")' 2>&1 | head -20
echo "ERRORS $(sf data query --query "SELECT Quote.QuoteNumber, Status, CreatedDate FROM QuoteLineItem WHERE CreatedDate >= 2026-11-26T11:20:00Z LIMIT 1" --target-org target --json 2>&1 | jq -r '.message // "none"')"
